    /// A pron form. The best candidate; the word itself if nothing is known.
    pub fn pron(&self, word: &str, case: Case, number: Number, gender: Gender, animacy: Animacy) -> String {
        best(self.pron_scored(word, case, number, gender, animacy), word)
    }

    /// Dictionary spelling of a pron (with stress marks where the data has them).
    pub fn pron_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(3, word)).unwrap_or_else(|| word.to_string())
    }

